// Parse da resposta JSON do Claude
const resposta = $input.first().json.text || $input.first().json.content || '';

let dados;
try {
  // Tenta extrair JSON da resposta (Claude às vezes adiciona markdown)
  const jsonMatch = resposta.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('JSON não encontrado na resposta');
  dados = JSON.parse(jsonMatch[0]);
} catch (e) {
  return [{ json: { erro: 'Falha ao parsear resposta do Claude: ' + e.message, resposta_bruta: resposta } }];
}

// Determinar o mês a partir da resposta ou do parâmetro enviado
const mesesMap = {
  'janeiro': 'Janeiro', 'fevereiro': 'Fevereiro', 'março': 'Março', 'marco': 'Março',
  'abril': 'Abril', 'maio': 'Maio', 'junho': 'Junho', 'julho': 'Julho',
  'agosto': 'Agosto', 'setembro': 'Setembro', 'outubro': 'Outubro',
  'novembro': 'Novembro', 'dezembro': 'Dezembro'
};

const mesRaw = (dados.mes || '').toLowerCase().trim();
const mes = mesesMap[mesRaw] || dados.mes || 'Outros';

// Formatar lançamentos
const lancamentos = (dados.lancamentos || []).map(l => ({
  mes: mes,
  banco: dados.banco || 'N/A',
  periodo: dados.periodo || '',
  data: l.data || '',
  descricao: l.descricao || '',
  categoria: l.categoria || 'Outros',
  tipo: l.tipo || 'Despesa',
  valor: parseFloat(l.valor) || 0,
  forma_pagamento: l.forma_pagamento || 'Outros',
  parcelas: parseInt(l.parcelas) || 1,
  observacoes: l.observacoes || ''
}));

// Retornar metadados + array de lançamentos
return [{
  json: {
    mes,
    banco: dados.banco || 'N/A',
    periodo: dados.periodo || '',
    total_despesas: dados.total_despesas || 0,
    total_receitas: dados.total_receitas || 0,
    quantidade: lancamentos.length,
    lancamentos
  }
}];

// Expande o array de lançamentos para itens individuais do N8N
const dados = $input.first().json;
const lancamentos = dados.lancamentos || [];

return lancamentos.map(l => ({ json: l }));

// Agrega todos os lançamentos processados
const items = $input.all();
const lancamentos = items.map(i => i.json);

const total_despesas = lancamentos
  .filter(l => l.tipo === 'Despesa')
  .reduce((s, l) => s + l.valor, 0);

const total_receitas = lancamentos
  .filter(l => l.tipo === 'Receita')
  .reduce((s, l) => s + l.valor, 0);

// Agrupa por categoria
const por_categoria = {};
lancamentos.forEach(l => {
  if (l.tipo === 'Despesa') {
    por_categoria[l.categoria] = (por_categoria[l.categoria] || 0) + l.valor;
  }
});

const categorias_ordenadas = Object.entries(por_categoria)
  .sort((a, b) => b[1] - a[1])
  .map(([cat, val]) => ({ categoria: cat, valor: val.toFixed(2) }));

return [{
  json: {
    mes: lancamentos[0]?.mes || '',
    banco: lancamentos[0]?.banco || '',
    total_lancamentos: lancamentos.length,
    total_despesas: total_despesas.toFixed(2),
    total_receitas: total_receitas.toFixed(2),
    saldo: (total_receitas - total_despesas).toFixed(2),
    top_categorias: categorias_ordenadas.slice(0, 5),
    lancamentos
  }
}];
